import { useState, type ChangeEvent, type FormEvent } from 'react';
import {
  Alert,
  Button,
  Card,
  Select,
  Stack,
  Switch,
  TextField,
} from '@jinx-ui/react';

type Role = 'viewer' | 'editor' | 'admin';

const ROLE_OPTIONS: Array<{ value: Role; label: string }> = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('viewer');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const trimmedEmail = email.trim();
  const isEmailValid = EMAIL_PATTERN.test(trimmedEmail);
  const hasError = touched && !isEmailValid;

  const handleEmailChange = (event: ChangeEvent<HTMLInputElement>) => {
    setEmail(event.target.value);
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isEmailValid) return;

    setInvitedEmail(trimmedEmail);
    setEmail('');
    setTouched(false);
    setRole('viewer');
  };

  return (
    <Card className="jx-card">
      <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
        {invitedEmail && (
          <Alert
            variant="success"
            title="Приглашение отправлено"
            closable
            onClose={() => setInvitedEmail(null)}
          >
            Мы пригласили {invitedEmail} в команду.
          </Alert>
        )}

        <form onSubmit={handleSubmit} noValidate>
          <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
            <TextField
              type="email"
              name="email"
              label="Почта участника"
              placeholder="name@company.com"
              value={email}
              onChange={handleEmailChange}
              onBlur={() => setTouched(true)}
              invalid={hasError}
              description="Пригласим по этому адресу, участник получит ссылку для входа."
              errorText="Введите корректный адрес почты, например name@company.com."
              autoComplete="email"
              required
            />

            <Select
              name="role"
              label="Роль в команде"
              value={role}
              onChange={(value: Role) => setRole(value)}
              options={ROLE_OPTIONS}
            />

            <Switch
              name="notify"
              label="Отправить уведомление"
              description="Участник получит письмо сразу после приглашения."
              checked={notify}
              onChange={(event: ChangeEvent<HTMLInputElement>) =>
                setNotify(event.target.checked)
              }
            />

            <Button type="submit" variant="primary" disabled={!isEmailValid}>
              Отправить приглашение
            </Button>
          </Stack>
        </form>
      </Stack>
    </Card>
  );
}

